{"output": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full single-color lines are the panel dividers.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    r_edges = [-1] + sep_rows + [h]
    c_edges = [-1] + sep_cols + [w]
    row_panels = [(r_edges[i] + 1, r_edges[i + 1]) for i in range(len(r_edges) - 1)]
    col_panels = [(c_edges[i] + 1, c_edges[i + 1]) for i in range(len(c_edges) - 1)]
    divider = {(r, c) for r in sep_rows for c in range(w)}
    divider |= {(r, c) for c in sep_cols for r in range(h)}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w) if (r, c) not in divider)
    background = counts.most_common(1)[0][0]
    panels = []
    for ri, (r0, r1) in enumerate(row_panels):
        for ci, (c0, c1) in enumerate(col_panels):
            cells = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            ink = sum(v != background for row in cells for v in row)
            panels.append((ink, ri, ci, cells))
    _, src_ri, src_ci, source = max(panels, key=lambda p: p[0])
    sh, sw = len(source), len(source[0])
    out = [row[:] for row in grid]
    for _, ri, ci, _ in panels:
        if (ri, ci) == (src_ri, src_ci):
            continue
        r0, r1 = row_panels[ri]
        c0, c1 = col_panels[ci]
        if (r1 - r0, c1 - c0) == (sh, sw):
            for dr in range(sh):
                for dc in range(sw):
                    out[r0 + dr][c0 + dc] = source[dr][dc]
    return out


